<script setup>
import { ref, watch } from 'vue'
import { FileUp, LoaderCircle } from 'lucide-vue-next'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '../ui/dialog'
import { Button } from '../ui/button'
import { api } from '../../workspace/api'
import { loadCustomSkills } from '../../workspace/featureCatalog'
const props = defineProps({ open: Boolean, skill: { type: Object, default: null }, theme: { type: String, default: 'light' } })
const emit = defineEmits(['update:open','saved','deleted'])
const form = ref({ name:'', description:'', instructions:'', group:'Custom skills', source_url:'' }), error = ref(''), saving = ref(false), fileInput = ref(null)
const groups = ['Custom skills','Workspace','Buyer research','Advertising','Strategy','Go to market','Validation']
watch(() => props.open, value => { if (value) { const skill = props.skill; form.value = { name:skill?.label || '', description:skill?.description || '', instructions:skill?.instructions || '', group:skill?.group || 'Custom skills', source_url:skill?.sourceUrl || '' }; error.value = '' } })
async function importText(event) {
 const file = event.target.files?.[0]; if (!file) return
 try { if (!/\.(md|txt)$/i.test(file.name)) throw new Error('Choose a Markdown or plain text file.'); if (file.size > 60000) throw new Error('Choose a text file under 60 KB.'); const text = await file.text(); if (text.length > 12000) throw new Error('Keep skill instructions under 12,000 characters.'); form.value.instructions = text; if (!form.value.name) form.value.name = file.name.replace(/\.[^.]+$/, '').slice(0,120); error.value = '' } catch (err) { error.value = err.message } finally { event.target.value = '' }
}
async function save() {
 saving.value = true; error.value = ''
 try { const path = props.skill ? `/api/workspace/skills/${encodeURIComponent(props.skill.skillId)}` : '/api/workspace/skills'; const value = await api(path,{method:props.skill?'PATCH':'POST',body:form.value}); await loadCustomSkills(true); emit('saved',value); emit('update:open',false) } catch (err) { error.value = err.message } finally { saving.value = false }
}
async function remove() {
 if (!props.skill) return
 if (!confirm(`Delete ${props.skill.label}? Its instructions are deleted and cannot be recovered.`)) return
 saving.value = true; error.value = ''
 try { await api(`/api/workspace/skills/${encodeURIComponent(props.skill.skillId)}`,{method:'DELETE'}); await loadCustomSkills(true); emit('deleted',props.skill.skillId); emit('update:open',false) } catch (err) { error.value = err.message } finally { saving.value = false }
}
</script>
<template>
 <Dialog :open="open" @update:open="emit('update:open',$event)"><DialogContent class="ws-overlay custom-skill-dialog" :data-theme="theme"><DialogHeader><DialogTitle>{{ skill ? 'Edit your skill' : 'Add a skill' }}</DialogTitle><DialogDescription>Save instructions you can reuse from chat. A skill prepares your message and uses your configured model.</DialogDescription></DialogHeader><form @submit.prevent="save"><div class="custom-skill-grid"><label>Name<input v-model="form.name" required maxlength="120" placeholder="For example, Weekly ad review" /></label><label>Category<select v-model="form.group"><option v-for="group in groups" :key="group">{{ group }}</option></select></label></div><label>Description<input v-model="form.description" maxlength="300" placeholder="When should this skill be used?" /></label><div class="custom-skill-instructions"><label>Instructions<textarea v-model="form.instructions" required maxlength="12000" rows="8" placeholder="Describe the task, required evidence, and the response you want…" /></label><div><span>{{ form.instructions.length.toLocaleString() }} / 12,000 characters</span><button type="button" @click="fileInput?.click()"><FileUp :size="13" />Import Markdown or text</button></div></div><label>Source link <small>Optional</small><input v-model="form.source_url" type="url" maxlength="2000" placeholder="https://github.com/owner/repository/blob/main/SKILL.md" /></label><p class="custom-skill-note">Paste instructions from a source you trust. The source link is saved for reference; code and GitHub files are not fetched or executed.</p><p v-if="error" class="custom-skill-error" role="alert">{{ error }}</p><footer><button v-if="skill" type="button" class="custom-skill-delete" :disabled="saving" @click="remove">Delete skill</button><Button type="button" variant="outline" @click="emit('update:open',false)">Cancel</Button><Button type="submit" :disabled="saving"><LoaderCircle v-if="saving" :size="14" />{{ saving ? 'Saving…' : 'Save skill' }}</Button></footer></form><input ref="fileInput" type="file" accept=".md,.txt,text/markdown,text/plain" hidden @change="importText" /></DialogContent></Dialog>
</template>
<style>
.custom-skill-dialog{width:min(650px,calc(100vw - 32px));max-width:650px!important;max-height:90dvh;overflow:auto;border-radius:23px!important;background:var(--panel)!important;border-color:var(--line)!important;color:var(--text)!important;padding:27px!important}.custom-skill-dialog [data-slot=dialog-description]{font-size:12px;color:var(--muted);line-height:1.7}.custom-skill-dialog form{display:grid;gap:17px}.custom-skill-dialog label{display:flex;flex-direction:column;gap:7px;font-size:12px;font-weight:500}.custom-skill-dialog input:not([type=file]),.custom-skill-dialog select,.custom-skill-dialog textarea{width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:9px;background:var(--panel-2);font:inherit;color:var(--text);font-weight:400}.custom-skill-dialog textarea{font-size:12px;line-height:1.8;resize:vertical}.custom-skill-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.custom-skill-dialog label small{font-size:10px;color:var(--muted);font-weight:400}.custom-skill-instructions>div{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:8px;color:var(--muted);font-size:10px}.custom-skill-instructions button{display:flex;align-items:center;gap:5px;background:none;border:0;color:var(--muted);font:inherit;cursor:pointer}.custom-skill-note{color:var(--muted);font-size:10px;line-height:1.7}.custom-skill-error{color:#b96760;font-size:12px;line-height:1.7}.custom-skill-dialog footer{display:flex;align-items:center;justify-content:flex-end;gap:9px;padding-top:5px}.custom-skill-dialog footer button[type=submit]{background:var(--accent);color:white}.custom-skill-delete{margin-right:auto;background:none;border:0;padding:8px 0;color:#b96760;font-size:11px;cursor:pointer}.custom-skill-dialog :focus-visible{outline:2px solid var(--accent);outline-offset:2px}@media(max-width:550px){.custom-skill-grid{grid-template-columns:1fr}.custom-skill-dialog{padding:21px!important}}
</style>
